#include "model.h"
bool suspend_task(task_t*t){if(!t||t->state==SUSPENDED)return false;t->ready_link=false;t->wait_link=false;t->timeout_link=false;t->result=3;t->state=SUSPENDED;return true;}bool resume_task(task_t*t){if(!t||t->state!=SUSPENDED)return false;t->state=READY;t->ready_link=true;t->result=1;return true;}bool timeout_wake(task_t*t){if(!t||t->state!=BLOCKED)return false;t->wait_link=false;t->timeout_link=false;t->ready_link=true;t->state=READY;t->result=2;return true;}bool validate_task(const task_t*t){if(!t)return false;if(t->state==SUSPENDED&&(t->ready_link||t->wait_link||t->timeout_link))return false;if(t->state==BLOCKED&&t->ready_link)return false;if(t->state==READY&&!t->ready_link)return false;return true;}
